RPT = ['key:Escape', 'user:manager', 'click:menutop:Accounts & Reports']
chapter(20, 'Reports and the Report hub', 'Read the Reports page, choose a period, find reports in the library, mark favourites, see scheduled runs and the export log, and read revenue by category and the owner digest.',
        'Meera (Manager)', 'manager', menu='Accounts & Reports > Reports')
step('Meera, the Manager, is on Modules Home. All figures of the hotel come out of the Accounts & Reports module.', 'A manager decides with figures, not with memory.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:manager'], action='read', expect='Modules Home for Meera.', check="ctx.uid==='manager'")
tile('Accounts & Reports', 'Click the Accounts & Reports tile.', 'Reports, the report library, revenue by category and the owner digest are listed here.', expect='The Accounts & Reports page opens.')
leaf('Accounts & Reports', 'Reports', 'Click the Reports tile.', 'This page gives the standard reports for a period.', expect='The Reports page opens.', check="ctx.page==='reports'")
read('At the top are the period buttons Today, Last 3 days, Last 7 days, Last 30 days, This month and FY history, and the From and To dates. Below are the report names: Daily operations, Revenue & tax, Receipts & deposits, Expenses & cash, Occupancy and the Report dictionary.', 'Every report has a period, so the same report serves a day and a month.', target='btn:Last 7 days', expect='The period buttons and the report names.')
click('btn:Last 7 days', 'Click Last 7 days.', 'The dates and every figure change at once.', expect='The period is the last seven days.')
click('btn:Revenue & tax', 'Click Revenue & tax.', 'This report shows the room and food revenue with the GST split.', expect='The revenue and tax report opens.')
read('Each report can be exported as CSV or Excel, or printed. The source rows behind every figure open with the view link, so a total can always be traced to the bills.', 'A figure that cannot be traced is not trusted.', target='btn:Export CSV', expect='The export and print buttons.')
click('btn:Report dictionary', 'Click Report dictionary.', 'The dictionary explains every figure: what it counts and what it leaves out.', expect='The dictionary opens.')
step('Open Report library under Accounts & Reports. It lists every report by group: Guests, Rooms, Money & cash and Tax & GST.', 'The library has more reports than the Reports page, with search and favourites.', target='sel:main h1', auto=['key:Escape', 'click:menutop:Accounts & Reports', 'click:menuleaf:Report library'], action='click', menu='Accounts & Reports > Report library', expect='The Report library opens.', check="ctx.page==='report-hub'")
typ('field:Search reports', 'cash', 'Type cash in the search box.', 'The list narrows to reports with that word.', expect='Only cash reports are listed.')
click('btn:Add to favourites: Cash book', 'Click Add to favourites on Cash book.', 'A favourite stays at the top of your list on your own login.', expect='The Cash book is a favourite.')
tick('field:Favourites only', 'Tick Favourites only.', 'Your daily reports are one click away.', expect='Only favourites are listed.')
click('tab:Scheduled runs', 'Open the Scheduled runs tab.', 'A report can be scheduled to run every morning and be sent to the owner; a schedule runs with the rights of the person who made it.', expect='The scheduled runs are listed.')
click('tab:Export log', 'Open the Export log tab.', 'Every export is logged with the user and the time, because a report can contain personal data.', expect='The export log opens.')
step('Open Revenue by category under Accounts & Reports.', 'It splits revenue by room type and the collections by payment method.', target='sel:main h1', auto=['key:Escape', 'click:menutop:Accounts & Reports', 'click:menuleaf:Revenue by category'], action='click', menu='Accounts & Reports > Revenue by category', expect='Revenue by category and tender opens.', check="ctx.page==='revenue-category'")
click('tab:B. Collections by tender', 'Open B. Collections by tender.', 'Cash, UPI, card and bank transfer are totalled separately, so the day\'s money can be matched with the bank and the drawer.', expect='The collections by tender are shown.')
click('tab:C. Bridge', 'Open C. Bridge.', 'The bridge shows how the revenue figure becomes the collection figure: advances, deposits, credit and tax.', expect='The bridge from revenue to collections opens.')
step('Sagar, the Owner, opens the Owner digest. It is the morning page: yesterday on one sheet.', 'The owner reads one page a day instead of ten reports.', target='sel:main h2', auto=['key:Escape', 'user:owner', 'click:menutop:Accounts & Reports', 'click:menuleaf:Owner digest'], action='click', menu='Accounts & Reports > Owner digest', expect='The Owner digest opens for 25 Oct 2026.', check="ctx.page==='owner-digest'")
read('The digest shows occupancy, revenue, collections, cash, expenses, pending approvals and exceptions for the chosen business date. Print puts it on one page, and the Outbox drafts below are the messages that would carry it to the owner by e-mail or phone.', 'If a figure looks wrong, the owner asks the manager the same morning.', target='btn:Print', expect='The digest of the day.')
